import type { HTMLAttributes, ReactNode } from 'react';
import { cn } from '@/lib/utils/cn';

interface Props extends HTMLAttributes<HTMLDivElement> {
  variant?: 'default' | 'elevated' | 'glass' | 'interactive';
  padding?: 'sm' | 'md' | 'lg';
  children: ReactNode;
}

const VARIANTS = {
  default: 'bg-surface border border-border',
  elevated: 'bg-surface-elevated border border-border shadow-lg',
  glass: 'glass',
  interactive:
    'bg-surface border border-border cursor-pointer hover:border-primary hover:shadow-[0_0_20px_rgba(139,92,246,0.2)] transition-all',
};

const PADDING = { sm: 'p-3', md: 'p-5', lg: 'p-7' };

export function Card({
  variant = 'default',
  padding = 'md',
  className,
  children,
  ...rest
}: Props) {
  return (
    <div
      className={cn('rounded-xl', VARIANTS[variant], PADDING[padding], className)}
      {...rest}
    >
      {children}
    </div>
  );
}